<?php require 'config.php'; require 'lib.php'; need_login(); track_user(); csrf_check(); if($_SERVER['REQUEST_METHOD']==='POST'&&!is_admin()){ http_response_code(403); exit(t('Du har bara läsbehörighet.','You have read-only access.')); }
$TY=nw_types(); $RO=nw_roles();
function nconn0($old){ return ['snmp'=>snmp_param_build($_POST['s_ver']??'2',$_POST,$old['snmp']??'')]; }
function nconn($old){ return nw_conn_iv(nconn0($old)); }
function nrole(){ $t=$_POST['type']??''; $r=$_POST['role']??''; return isset(nw_roles()[$r])?$r:(in_array($t,['opnsense','pfsense'],true)?'firewall':'switch'); }
if($_SERVER['REQUEST_METHOD']==='POST'){ $a=$_POST['a']??''; $hid=(int)($_POST['id']??$_POST['cid']??0); $pdo=db();
 if($a==='add'&&isset($TY[$_POST['type']??''])&&trim($_POST['host']??'')!==''){ $h=trim($_POST['host']);
  $pdo->prepare('INSERT INTO servers(name,host,nw_type,nw_role,nw_conn) VALUES(?,?,?,?,?)')->execute([trim($_POST['name']??'')?:$h,$h,$_POST['type'],nrole(),json_encode(nconn([]))]); $nid=$pdo->lastInsertId();
  $pdo->prepare("INSERT INTO server_checks(server_id,source,kind,target,label) VALUES(?,'tcp','ping','','Ping')")->execute([$nid]); applog('info','config','Network device added: '.$h); $_SESSION['flash']=t('Enhet tillagd – första SNMP-avläsningen sker inom en minut (klicka på Testa nu för att se felmeddelanden direkt).','Device added – the first SNMP reading happens within a minute (click Test now to see any error right away).'); }
 if($a==='edit'&&isset($TY[$_POST['type']??''])&&trim($_POST['host']??'')!==''){ $q2=$pdo->prepare('SELECT nw_conn FROM servers WHERE id=?'); $q2->execute([$hid]); $old=json_decode((string)$q2->fetchColumn(),true)?:[]; $h=trim($_POST['host']);
  $pdo->prepare('UPDATE servers SET name=?,host=?,comment=?,nw_type=?,nw_role=?,nw_conn=?,nw_poll=NULL WHERE id=? AND nw_type IS NOT NULL')->execute([trim($_POST['name']??'')?:$h,$h,trim($_POST['comment']??''),$_POST['type'],nrole(),json_encode(nconn($old)),$hid]); }
 if($a==='test'){ $q=$pdo->prepare('SELECT * FROM servers WHERE id=? AND nw_type IS NOT NULL'); $q->execute([$hid]); if($s=$q->fetch()){ $r=poll_network($s); $_SESSION['flash']=$r['ok']?('✔ '.$s['name'].': CPU '.($r['data']['cpu']!==null?$r['data']['cpu'].'%':'–').', '.t('minne','memory').' '.($r['data']['mem']!==null?$r['data']['mem'].'%':'–').', '.count($r['ifs']).' interface'):('✖ '.$s['name'].': '.$r['error']); } }
 if($a==='toggle'){ $pdo->prepare('UPDATE servers SET enabled=1-enabled,nw_poll=NULL WHERE id=? AND nw_type IS NOT NULL')->execute([$hid]); $pdo->prepare('UPDATE server_checks SET last_check=NULL WHERE server_id=?')->execute([$hid]); }
 if($a==='toggle_dash') $pdo->prepare('UPDATE servers SET dash_hidden=1-dash_hidden WHERE id=? AND nw_type IS NOT NULL')->execute([$hid]);
 if($a==='del'){ applog('warning','config','Network device deleted, id '.$hid); $q=$pdo->prepare('SELECT id FROM server_checks WHERE server_id=?'); $q->execute([$hid]); purge_targets([$hid],array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN))); $pdo->prepare('DELETE FROM servers WHERE id=? AND nw_type IS NOT NULL')->execute([$hid]); }
 header('Location: '.((($_POST['back']??'')==='detail'&&$a!=='del')?'netdev.php?id='.$hid:'network.php'));exit; }
$ed=null; $ec=[]; if(isset($_GET['edit'])&&is_admin()){ $q=db()->prepare('SELECT * FROM servers WHERE id=? AND nw_type IS NOT NULL'); $q->execute([(int)$_GET['edit']]); $ed=$q->fetch()?:null; $ec=$ed?(json_decode((string)$ed['nw_conn'],true)?:[]):[]; }
$sp=snmp_param_parse($ec['snmp']??'');
top(t('Nätverk','Network')); flash(); ?>
<h2><?= t('Nätverk','Network') ?></h2>
<?php if(is_admin()): ?><form method="post" class="card inline"><?= csrf_field() ?><input type="hidden" name="a" value="<?= $ed?'edit':'add' ?>"><?php if($ed) echo '<input type="hidden" name="id" value="'.$ed['id'].'">'; ?>
<select name="type" id="ntype"><?php foreach($TY as $k=>$n) echo '<option value="'.$k.'"'.(($ed['nw_type']??'cisco')===$k?' selected':'').'>'.h($n).'</option>'; ?></select>
<select name="role" id="nrole"><?php foreach($RO as $k=>$n) echo '<option value="'.$k.'"'.(($ed['nw_role']??'switch')===$k?' selected':'').'>'.h($n).'</option>'; ?></select>
<input name="name" value="<?= h($ed['name']??'') ?>" placeholder="<?= t('Namn (valfritt)','Name (optional)') ?>"><input name="host" value="<?= h($ed['host']??'') ?>" placeholder="<?= 'IP/Hostname' ?>" required>
<?= nw_iv_input($ec) ?><input name="s_port" type="number" min="1" max="65535" style="width:110px" value="<?= h($sp["port"]??"") ?>" placeholder="<?= t("Port (standard 161)","Port (default 161)") ?>"> <select name="s_ver" class="sver"><option value="2"<?= $sp['ver']==='2'?' selected':'' ?>>SNMP v2c</option><option value="3"<?= $sp['ver']==='3'?' selected':'' ?>>SNMP v3 (<?= t('standardinställningar','defaults') ?>)</option></select><input class="s2f" name="s_comm" value="<?= h($sp['comm']) ?>" placeholder="<?= 'Community' ?>"><?= snmp_v3_fields($sp) ?>
<?php if($ed): ?><label class="f" style="min-width:260px"><?= t('Kommentar','Comment') ?><textarea name="comment" rows="1" cols="30"><?= h($ed['comment']??'') ?></textarea></label><?php endif; ?>
<button class="btn"><?= $ed?t('Spara ändringar','Save changes'):t('Lägg till enhet','Add device') ?></button><?php if($ed) echo '<a class="btn danger" href="network.php">'.t('Avbryt','Cancel').'</a>'; ?></form><?php if(!$ed) echo nw_remember_js('nw'); ?>
<script>(function(){var t=document.getElementById('ntype'),r=document.getElementById('nrole');t.onchange=function(){if(t.value==='opnsense'||t.value==='pfsense')r.value='firewall'}})();</script>
<?php endif; ?>
<?php $IFS=tc_ifs_by_server(); ?><table class="card"<?= tc_attr('network') ?>><tr><th data-k="name"><?= t('Namn','Name') ?></th><th data-k="type"><?= t('Typ','Type') ?></th><th data-k="model"><?= t('Modell','Model') ?></th><th data-k="addr"><?= t('Adress','Address') ?></th><th data-k="ping">Ping</th><th data-k="snmp">SNMP</th><th data-k="ports"><?= t('Portar upp','Ports up') ?></th><th data-k="last"><?= t('Senaste kontroll','Last check') ?></th><?= tc_th('topif',t('Mest trafikerade port','Top interface')) ?><?= tc_th('poe','PoE') ?><?= tc_th('cl',t('Wi-Fi-klienter','Wi-Fi clients')) ?><?= tc_th('upt','Uptime') ?><?= tc_th('cpu','CPU') ?><?= tc_th('mem',t('Minne','Memory')) ?><?= tc_th('temp',t('Temperatur','Temperature')) ?><?= tc_th('err',t('Fel/min','Errors/min')) ?><?= tc_th('traf',t('Trafik in / ut','Traffic in / out')) ?><?= tc_th('host','Hostname') ?><?= tc_th('ser',t('Serienummer','Serial number')) ?><?= tc_th('loc',t('Plats','Location')) ?><?= tc_th('fw',t('Beskrivning / firmware','Description / firmware')) ?><?= tc_th('cmt',t('Kommentar','Comment')) ?><?= tc_th('grp',t('Grupper','Groups')) ?><?= dg_ths() ?><th></th></tr>
<?php foreach(db()->query("SELECT s.*,TIMESTAMPDIFF(SECOND,nw_poll,NOW()) AS age,(SELECT last_status FROM server_checks c WHERE c.server_id=s.id AND c.kind='ping' LIMIT 1) ping,(SELECT COUNT(*) FROM net_if n WHERE n.server_id=s.id) nif,(SELECT COUNT(*) FROM net_if n WHERE n.server_id=s.id AND n.oper=1) nup FROM servers s WHERE s.nw_type IS NOT NULL AND (s.nw_role IS NULL OR s.nw_role NOT IN ('nas','san','bmc')) ORDER BY s.name") as $s): $d=json_decode((string)$s['nw_data'],true)?:[]; $en=(int)$s['enabled']===1; ?>
<tr class="<?= $en?'':'dim' ?>" data-href="netdev.php?id=<?= $s['id'] ?>"><td><b class="rn"><?= h($s['name']) ?></b><?= $en?'':' <small>('.t('inaktiverad','disabled').')</small>' ?><?= !empty($s['dash_hidden'])?' <small>('.t('dold på dash','hidden on dash').')</small>':'' ?><?= trim((string)$s['comment'])!==''?'<br><small class="mut">'.h($s['comment']).'</small>':'' ?></td><td><?= h($RO[$s['nw_role']]??'') ?> · <?= h(explode(' (',$TY[$s['nw_type']]??$s['nw_type'])[0]) ?></td><td class="det"><?= h($d['model']??'–') ?></td><td><?= h($s['host']) ?></td>
<td class="<?= $s['ping']==='up'?'okt':($s['ping']?'badt':'') ?>"><?= $s['ping']?:t('väntar','pending') ?></td><td class="det <?= $s['nw_status']==='up'?'okt':($s['nw_status']?'badt':'') ?>"><?= $s['nw_status']?h($s['nw_status']).($s['nw_error']?' – '.h($s['nw_error']):''):t('väntar','pending') ?></td><td><?= $s['nif']?$s['nup'].' / '.$s['nif']:'–' ?></td><td><?= $s['age']===null?'–':($s['age']<60?$s['age'].' s':floor($s['age']/60).' min') ?></td>
<?php $ifr=$IFS[$s['id']]??[]; echo tc_topif($ifr);
 $po=$d['poe']??null; if($po&&!empty($po['ports'])){ $pn=count(array_filter($po['ports'],fn($x)=>($x['s']??0)===3)); echo '<td data-sort="'.(float)($po['use']??$pn).'">'.$pn.' / '.count($po['ports']).(isset($po['use'])?' · '.round($po['use'],1).' W':'').'</td>'; } else echo '<td class="mut">–</td>';
 echo tc_td(isset($d['wifi']['clients'])?(string)(int)$d['wifi']['clients']:null),tc_td(!empty($d['uptime'])?tc_upt($d['uptime']):null,(int)($d['uptime']??0)),bar_cell($d['cpu']??null,'cpu'),bar_cell($d['mem']??null,'mem'),tc_td(isset($d['temp'])?round($d['temp']).' °C':null,$d['temp']??null);
 $er=null; foreach($ifr as $x) if($x['err_pm']!==null) $er=($er??0)+(float)$x['err_pm']; echo tc_td($er!==null?round($er,1):null,$er);
 $ti=0; $to=0; foreach($ifr as $x){ if((int)$x['oper']===1){ $ti+=(float)$x['rate_in']; $to+=(float)$x['rate_out']; } } echo $ifr?'<td data-sort="'.(int)($ti+$to).'">'.h(fmt_bps($ti)).' / '.h(fmt_bps($to)).'</td>':'<td class="mut">–</td>';
 echo tc_td($d['hostname']??null),tc_td($d['serial']??null),tc_td($d['location']??null),tc_td(isset($d['descr'])?mb_strimwidth((string)$d['descr'],0,90,'…'):null),tc_td($s['comment']??null); ?>
<?= dg_td($s['id']) ?><?= dg_tds($s['id']) ?><td class="inline"><?php if(is_admin()): ?><a class="btn sm" href="network.php?edit=<?= $s['id'] ?>"><?= t('Ändra','Edit') ?></a><?= fbtn('toggle',$s['id'],$en?t('Inaktivera','Disable'):t('Aktivera','Enable'),$en?'warn':'go') ?><?= fbtn('del',$s['id'],t('Ta bort','Delete'),'danger',t('Ta bort enheten och all dess data?','Delete the device and all its data?')) ?><?php endif; ?></td></tr>
<?php endforeach; ?></table>
<?php bottom();
